igés ; les cautions de gobelets restent séparées. Ne pas additionner ce plafond à celui de la campagne candidats : ce sont en partie les mêmes paiements.</p><h3>Affectations par freguesia · billets confirmés uniquement</h3><table><thead><tr><th>Freguesia</th><th>Billets</th><th>Brut</th><th>Junta</th><th>Stand / défi</th></tr></thead><tbody>@foreach($report['freguesias'] as $village)<tr><td>{{ $village['name'] }}</td><td>{{ $village['tickets'] }}</td><td>{{ \App\Domain\Finance\Money::format($village['gross_cents']) }}</td><td>{{ \App\Domain\Finance\Money::format($village['junta_cents']) }}</td><td>{{ \App\Domain\Finance\Money::format($village['village_cents']) }}</td></tr>@endforeach</tbody></table></div>